llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Asciminib, a complex heteroaromatic drug with multiple polar groups, has an absolute oral bioavailability of approximately 73% in humans, demonstrating that high F is achievable for structurally complex, polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Levofloxacin, a fluoroquinolone with a carboxylic acid and polar piperazine, is essentially completely bioavailable (99%) after oral dosing, supporting high F for ionizable, polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Doxifluridine, a polar nucleoside analog, shows oral bioavailability of 34–80% in humans, all above the 20% threshold, indicating that even highly polar molecules can meet the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pradigastat, a carboxylic acid-containing drug, has an absolute oral bioavailability of ~40% and is judged completely bioavailable at a 10 mg dose, supporting high F despite polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "LY2196044, a polar amide/ether with a piperidine, has an estimated bioavailability of 45%, above the 20% threshold, supporting high F for a moderately polar oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Zidovudine, a nucleoside with multiple polar hydroxyls and an azide, has a human oral bioavailability of ~63%, showing high F despite substantial polar character.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence, with assay-transfer scores near 0.99, reports oral bioavailability values above the 20% threshold (34–100%), including polar, ionizable, and complex heteroaromatic molecules. The physicochemical prior predicts low permeability due to the phosphate group and very low logD, but the strong, consistently high-F experimental evidence overrides this uncertain prior. Confidence is moderate because no direct phosphate-containing analogue was tested and the query's extreme polarity remains a unique feature.",
  "evidence_gaps": [
    "No direct experimental evidence for a phosphate monoester-containing analogue; potential intestinal phosphatase cleavage is not experimentally addressed.",
    "No human pharmacokinetic data exist for the query molecule itself.",
    "The query's extremely low logD and full ionization are not represented in the high-F evidence set, so extrapolation relies on assay-transfer scores rather than direct structural analogy."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

